#include <bits/stdc++.h>
using namespace std;

struct State {
    int sum, a, b;
};

struct FenwickMax {
    vector<int> bit;
    vector<int> offset;
    vector<int> degree;

    FenwickMax(const vector<vector<int>>& adj) {
        int n = adj.size();
        offset.resize(n);
        degree.resize(n);
        int total = 0;
        for (int v = 0; v < n; ++v) {
            offset[v] = total;
            degree[v] = adj[v].size();
            total += degree[v] + 1;
        }
        bit.assign(total, -1);
    }

    void update(int v, int index, int value) {
        int p = degree[v] - index;
        for (; p <= degree[v]; p += p & -p)
            bit[offset[v] + p] = max(bit[offset[v] + p], value);
    }

    int queryPrefix(int v, int count) const {
        int result = -1;
        for (int p = count; p > 0; p -= p & -p)
            result = max(result, bit[offset[v] + p]);
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> adj(N);
    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    for (auto& v : adj)
        sort(v.begin(), v.end());

    vector<State> states;
    states.reserve(2LL * M);
    for (int a = 0; a < N; ++a)
        for (int b : adj[a])
            states.push_back({a + b, a, b});

    sort(states.begin(), states.end(), [](const State& x, const State& y) {
        return x.sum > y.sum;
    });

    FenwickMax dpE(adj), dpO(adj);
    vector<int> answer(N, 1);

    for (const State& s : states) {
        int a = s.a, b = s.b;

        int first = upper_bound(adj[b].begin(), adj[b].end(), a) - adj[b].begin();
        int bestO = dpO.queryPrefix(b, (int)adj[b].size() - first);
        int valueE = bestO < 0 ? 0 : bestO + 1;

        first = upper_bound(adj[a].begin(), adj[a].end(), b) - adj[a].begin();
        int bestE = dpE.queryPrefix(a, (int)adj[a].size() - first);
        int valueO = bestE < 0 ? 0 : bestE + 1;

        int indexB = lower_bound(adj[a].begin(), adj[a].end(), b) - adj[a].begin();
        dpE.update(a, indexB, valueE);

        int indexA = lower_bound(adj[b].begin(), adj[b].end(), a) - adj[b].begin();
        dpO.update(b, indexA, valueO);

        answer[a] = max(answer[a], 2 + valueE);
    }

    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << answer[i];
    }
    cout << '\n';
    return 0;
}
